<script setup lang="ts">
import {ref,onUnmounted,watch} from 'vue';
import {onShow,onHide} from '@dcloudio/uni-app';
import UniIcons from '@club-ui/uni-icons/uni-icons.vue';
import {api,httpMode,useIdentity} from '../../store';
import {getPlatformLayout} from '../../services/platform';
import {money,time,requestKey,withdrawalLabels,type MemberWallet} from '@stellar/core';
const identity=useIdentity(),layout=ref(getPlatformLayout()),wallet=ref<MemberWallet|null>(null),error=ref(''),busy=ref(false),loading=ref(true),sheet=ref<'bank'|'withdraw'|null>(null);
const holder=ref(''),bankName=ref(''),bankNumber=ref(''),password=ref(''),amount=ref(''),consent=ref(false);
let timer:ReturnType<typeof setTimeout>|undefined,alive=false,key=requestKey(),keyAmount=0;
function clear(){holder.value='';bankName.value='';bankNumber.value='';password.value='';consent.value=false;}
function close(){sheet.value=null;clear();}
function back(){uni.navigateBack({fail:()=>uni.reLaunch({url:'/pages/index/index'})});}
async function load(silent=false){if(!silent)loading.value=true;const user=identity.session?.userId;try{if(httpMode&&!user)await identity.restore();const owner=identity.session?.userId;if(!owner)throw new Error('请先返回首页登录');const value=await api.memberWallet();if(identity.session?.userId===owner){wallet.value=value;error.value='';}}catch(e){error.value=e instanceof Error?e.message:'钱包加载失败';}finally{loading.value=false;}}
function schedule(){clearTimeout(timer);if(alive)timer=setTimeout(async()=>{await load(true);schedule();},30000);}
async function submit(){
 if(busy.value)return;busy.value=true;error.value='';const owner=identity.session?.userId;
 try{if(sheet.value==='bank'){await api.saveBank({holder:holder.value.trim(),bankName:bankName.value.trim(),bankNumber:bankNumber.value.replace(/\s/g,''),password:password.value,consent:consent.value});}
 else {const value=amount.value.trim();if(!/^\d+(\.\d{1,2})?$/.test(value))throw new Error('请输入最多两位小数的提现金额');const cents=Math.round(Number(value)*100);if(!Number.isSafeInteger(cents)||cents<100||cents>5000000)throw new Error('单次提现范围为1至50000元');if(cents!==keyAmount){key=requestKey();keyAmount=cents;}await api.withdraw(cents,password.value,key);key=requestKey();keyAmount=0;}
 if(owner===identity.session?.userId){close();await load(true);uni.showToast({title:'已提交',icon:'success'});}
 }catch(e){error.value=e instanceof Error?e.message:'操作失败，请重试';}finally{password.value='';busy.value=false;}
}
async function cancel(id:string){if(busy.value)return;uni.showModal({title:'撤销提现',content:'撤销后冻结金额将退回可提现余额。',success:async result=>{if(!result.confirm)return;busy.value=true;try{await api.cancelWithdrawal(id);await load(true);}catch(e){error.value=e instanceof Error?e.message:'撤销失败';}finally{busy.value=false;}}});}
watch(()=>identity.session?.userId,()=>{close();wallet.value=null;error.value='';key=requestKey();keyAmount=0;});
onShow(()=>{alive=true;layout.value=getPlatformLayout();void load();schedule();});onHide(()=>{alive=false;clearTimeout(timer);close();});onUnmounted(()=>{alive=false;clearTimeout(timer);clear();});
const entryLabel:Record<string,string>={credit:'订单收入',refund:'退款调整',freeze:'申请提现',unfreeze:'提现解冻',paid:'提现已付款'};
</script>
<template>
 <view class="member-wallet-page" :style="{'--club-safe-bottom':(layout?.safeBottom||0)+'px'}">
  <view class="topbar account-topbar" :style="layout?{height:layout.navHeight+'px',paddingTop:layout.topPadding+'px',paddingRight:layout.rightPadding+'px'}:{}"><button class="account-back" aria-label="返回我的" @tap="back"><UniIcons type="arrow-left" :size="23" color="#e9ebf1"/></button><view class="account-page-title">我的钱包</view><button class="account-refresh" aria-label="刷新钱包" :disabled="busy" @tap="load"><UniIcons type="refresh" :size="22" color="#aaaebe"/></button></view>
  <scroll-view class="wallet-scroll" :scroll-y="!sheet" :show-scrollbar="false"><view class="wallet-body">
   <view v-if="loading" class="wallet-muted">正在加载钱包…</view>
   <template v-else-if="wallet">
    <view class="wallet-balance"><text>可提现余额</text><view class="wallet-number"><text>¥</text>{{money(wallet.available)}}</view><view class="wallet-figures"><view><text>待结算</text><text class="wallet-emphasis">¥{{money(wallet.pending)}}</text></view><view><text>提现中</text><text class="wallet-emphasis">¥{{money(wallet.frozen)}}</text></view><view><text>累计已付款</text><text class="wallet-emphasis">¥{{money(wallet.settled)}}</text></view></view><button class="primary full" :disabled="busy||wallet.available<100" @tap="sheet=wallet.bank?'withdraw':'bank';amount='';clear()">申请提现</button></view>
    <view class="wallet-muted wallet-rule">订单完成{{wallet.holdHours?`满${wallet.holdHours}小时`:''}}后可提现，售后处理中暂停结算。提现由平台审核并人工转账，付款后更新记录。</view>
    <button class="wallet-bank" @tap="clear();sheet='bank'"><UniIcons type="wallet" :size="22" color="#bdb5f5"/><view><text>{{wallet.bank?wallet.bank.bankName+' · 尾号'+wallet.bank.lastFour:'设置收款银行卡'}}</text><text class="wallet-muted">{{wallet.bank?wallet.bank.maskedHolder+' · 本人账户，付款前人工核对':'仅支持本人银行卡'}}</text></view><UniIcons type="arrow-right" :size="16" color="#9299aa"/></button>
    <view v-if="wallet.simulation" class="wallet-simulation">另有模拟收入 ¥{{money(wallet.simulation)}}，仅供内部验收，不计入真实余额，不可提现。</view>
    <view class="wallet-section-title">提现记录<text>最近200笔</text></view><view v-if="!wallet.withdrawals.length" class="wallet-empty">暂无提现记录</view>
    <view v-for="w in wallet.withdrawals" :key="w.id" class="withdrawal-card"><view class="wallet-row"><text class="wallet-emphasis">¥{{money(w.amount)}}</text><text :class="{'wallet-paid':w.status==='paid'}">{{withdrawalLabels[w.status]}}</text></view><view class="wallet-muted">{{w.bankName}} · 尾号{{w.lastFour}} · {{time(w.createdAt)}}</view><view v-if="w.reviewNote" class="wallet-muted">审核：{{w.reviewNote}}</view><view v-if="w.paymentNote" class="wallet-muted">付款说明：{{w.paymentNote}}</view><view v-if="w.paymentReference" class="wallet-muted">流水：{{w.paymentReference}}</view><button v-if="w.status==='pending'" class="secondary small" :disabled="busy" @tap="cancel(w.id)">撤销申请</button></view>
    <view class="wallet-section-title">收支明细<text>最近100条</text></view><view v-if="!wallet.entries.length" class="wallet-empty">暂无收支明细</view><view v-for="e in wallet.entries" :key="e.id" class="wallet-entry"><view><text>{{entryLabel[e.kind]||e.kind}}<text v-if="e.fundMode==='simulation'" class="wallet-demo">模拟</text></text><text class="wallet-muted">{{time(e.createdAt)}}</text></view><text class="wallet-emphasis">{{e.amount<0?'−':''}}¥{{money(Math.abs(e.amount))}}</text></view>
   </template>
   <view v-if="error&&!sheet" class="wallet-error" role="alert">{{error}}<button v-if="!wallet" class="secondary small" @tap="load">重新加载</button></view>
  </view></scroll-view>
  <view v-if="sheet" class="wallet-mask" @tap.self="!busy&&close()"><view class="wallet-sheet"><view class="wallet-row"><text class="wallet-emphasis">{{sheet==='bank'?'收款银行卡':'申请提现'}}</text><button class="wallet-close" aria-label="关闭" :disabled="busy" @tap="close">×</button></view><scroll-view scroll-y class="wallet-form">
   <template v-if="sheet==='bank'"><view class="form-label">收款人姓名</view><input v-model="holder" class="form-input" aria-label="收款人姓名" placeholder="与实名认证填写姓名一致" :maxlength="60" :disabled="busy"/><view class="form-label">开户银行</view><input v-model="bankName" class="form-input" aria-label="开户银行" placeholder="例如：中国工商银行" :maxlength="80" :disabled="busy"/><view class="form-label">银行卡号</view><input v-model="bankNumber" class="form-input" aria-label="银行卡号" type="number" placeholder="本人银行卡号码" :maxlength="23" :disabled="busy"/><view class="wallet-muted">信息加密保存，仅用于报酬付款与核对。当前尚未接入银行卡实名核验，平台付款前人工核实。</view><button class="wallet-consent" role="checkbox" :aria-checked="consent" :disabled="busy" @tap="consent=!consent">{{consent?'☑':'□'}} 我确认使用本人账户，并同意为报酬结算处理上述收款信息</button></template>
   <template v-else><view class="form-label">提现金额（元）</view><input v-model="amount" class="form-input" aria-label="提现金额" type="digit" :maxlength="9" placeholder="最低1元，不超过可提现余额" :disabled="busy"/><view class="wallet-muted">可提现 ¥{{money(wallet?.available||0)}}，提交后冻结相应金额。状态不明时请勿重复发起不同金额的申请。</view></template>
   <view class="form-label">登录密码</view><input v-model="password" class="form-input" aria-label="登录密码" password :maxlength="72" :disabled="busy" placeholder="验证本人操作"/><view class="wallet-muted">尚未设置密码，请先前往我的 → 账号安全。</view><view v-if="error" class="wallet-error" role="alert">{{error}}</view><button class="primary full wallet-submit" :disabled="busy||!password||(sheet==='bank'&&!consent)" @tap="submit">{{busy?'正在提交…':sheet==='bank'?'保存收款账户':'提交提现申请'}}</button>
  </scroll-view></view></view>
 </view>
</template>
<style lang="scss">@import '../../styles/mobile.scss';</style>
<style scoped lang="scss">
.member-wallet-page{height:100dvh;max-width:520px;margin:auto;background:#101218;color:#e9ebf1;display:flex;flex-direction:column}.wallet-scroll{height:0;flex:1;min-height:0;overscroll-behavior:contain}.wallet-body{padding:22px 18px calc(32px + var(--club-safe-bottom))}.wallet-balance{padding:24px 20px;background:linear-gradient(135deg,#2a3424,#1d2428);border:1px solid #627642;border-radius:20px}.wallet-balance>text{font-size:13px;color:#c4cbb6}.wallet-number{font-size:42px;letter-spacing:-1px;font-weight:750;margin:10px 0 24px;color:#d9fd88}.wallet-number>text{font-size:22px;margin-right:4px}.wallet-figures{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:24px}.wallet-figures>view{display:flex;flex-direction:column;gap:8px}.wallet-figures text{font-size:11px;color:#aaaebe}.wallet-figures .wallet-emphasis{font-size:14px}.wallet-muted{font-size:11px;color:#989fb0;line-height:1.8;overflow-wrap:anywhere}.wallet-rule{padding:14px 3px}.wallet-bank{display:flex;align-items:center;gap:14px;text-align:left;padding:18px;background:#1b2029;border:1px solid #343c4c;border-radius:16px;color:#e9ebf1;font-size:14px}.wallet-bank>view{flex:1;display:flex;flex-direction:column;gap:4px}.wallet-simulation{padding:14px;border:1px dashed #48425a;color:#aaa4c8;border-radius:12px;margin-top:16px;font-size:11px;line-height:1.8}.wallet-section-title{display:flex;justify-content:space-between;align-items:center;font-size:17px;font-weight:650;margin:30px 0 16px}.wallet-section-title>text{font-size:10px;color:#7e8799;font-weight:400}.wallet-empty{text-align:center;padding:25px 0;color:#80889a;font-size:12px}.withdrawal-card{padding:16px;background:#1b2029;border:1px solid #303949;border-radius:14px;margin-bottom:12px}.wallet-row{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:10px}.wallet-row>text{font-size:12px;color:#bdb5f5}.wallet-row .wallet-paid{color:#d9fd88}.withdrawal-card>.secondary{margin:12px 0 0 auto}.wallet-entry{display:flex;justify-content:space-between;align-items:center;padding:16px 0;border-bottom:1px solid #272e3a;font-size:13px;gap:12px}.wallet-entry>view{display:flex;flex-direction:column;gap:5px}.wallet-demo{font-size:10px;background:#332d42;color:#bdb5f5;border-radius:4px;padding:2px 5px;margin-left:7px}.wallet-error{font-size:12px;color:#f2a3a3;margin:16px 0;line-height:1.8}.wallet-mask{position:fixed;inset:0;z-index:100;background:#0009;display:flex;justify-content:center;align-items:flex-end;padding:12px;box-sizing:border-box}.wallet-sheet{width:100%;max-width:480px;max-height:88dvh;background:#1b2029;border:1px solid #3b4659;border-radius:22px;padding:20px;box-sizing:border-box;display:flex;flex-direction:column}.wallet-sheet>.wallet-row>.wallet-emphasis{font-size:20px}.wallet-close{background:none;color:#aaaebe;font-size:27px;padding:0 4px;line-height:30px}.wallet-form{flex:1;min-height:0;max-height:72dvh}.wallet-form .form-input{box-sizing:border-box;height:46px;width:100%;padding:12px;background:#121720;border:1px solid #3a4354;border-radius:10px;font-size:13px;color:#e9ebf1}.wallet-form .wallet-muted{margin-top:10px}.wallet-consent{background:none;text-align:left;font-size:11px;color:#b9c6a4;line-height:1.8;padding:10px 0}.wallet-submit{margin:22px 0 calc(4px + var(--club-safe-bottom))}
</style>
